reference_solution:
def count_complete_nodes(root):
    def left_height(node):
        height = 0
        while node is not None:
            height += 1
            node = node.left
        return height
    total = 0
    while root is not None:
        left, right = left_height(root.left), left_height(root.right)
        if left == right:
            total += 1 << left
            root = root.right
        else:
            total += 1 << right
            root = root.left
    return total

